        if (turn < cSAngle(-w->mFrontAngle)) {
            globe.U(directionOf(w->mTarget) + cSAngle(-w->mFrontAngle));
        } else if (turn > cSAngle(w->mFrontAngle)) {
            globe.U(directionOf(w->mTarget) + cSAngle(w->mFrontAngle));
        }

